ground_truth:
def get_compatibility_mode(user_agent):
  ie_compat_modes = {
    'MSIE 7.0': 'IE7',
    'MSIE 8.0': 'IE8',
    'MSIE 9.0': 'IE9',
    'MSIE 10.0': 'IE10',
  }
  for ua in ie_compat_modes.keys():
    if ua in user_agent:
      return ie_compat_modes[ua]
  return 'Not IE or Compatibility Mode'

